B.aBU=new A.a4("1. \u041a\u04e3 \u0431\u0430\u0440\u043e\u0438 \u043c\u0430\u044a\u043b\u0443\u043c\u043e\u0442 \u043c\u0430\u0441\u044a\u0443\u043b \u0430\u0441\u0442","\u041e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0438 \u0445\u0438\u0434\u043c\u0430\u0442\u0438 \xabTAJ Bozor\xbb \u2014 \u041d\u0430\u0437\u0438\u0440\u043e\u0432 \u0425\u0443\u0448\u0431\u0430\u0445\u0442 \u0410\u0445\u0440\u043e\u0440\u043e\u0432\u0438\u0447 (\u0448\u0430\u0445\u0441\u0438 \u0432\u043e\u049b\u0435\u04e3). \u0411\u0430\u0440\u043e\u0438 \u043c\u0443\u0440\u043e\u04b7\u0438\u0430\u0442 \u0431\u0430 \u043c\u043e \u0431\u043e e-mail: support@tajbozor.pro \u0442\u0430\u043c\u043e\u0441 \u0433\u0438\u0440\u0435\u0434.")
B.aBa=new A.a4("2. \u041a\u0430\u0434\u043e\u043c \u043c\u0430\u044a\u043b\u0443\u043c\u043e\u0442\u0440\u043e \u04b7\u0430\u043c\u044a \u043c\u0435\u043a\u0443\u043d\u0435\u043c","\u041d\u043e\u043c, \u0441\u0443\u0440\u043e\u0493\u0430\u0438 \u043f\u043e\u0447\u0442\u0430\u0438 \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u04e3 \u0432\u0430 \u0448\u0438\u043d\u043e\u0441\u0430\u0438 \u0432\u043e\u0440\u0438\u0434\u0448\u0430\u0432\u04e3 (\u0442\u0430\u0432\u0430\u0441\u0441\u0443\u0442\u0438 Google, Apple \u0451 Telegram); \u0441\u0443\u0440\u043e\u0493\u0430\u0438 \u043f\u043e\u0447\u0442\u0430 \u0431\u0430\u0440\u043e\u0438 \u0433\u0438\u0440\u0438\u0444\u0442\u0430\u043d\u0438 \u0440\u0430\u043c\u0437\u04b3\u043e\u0438 \u0432\u043e\u0440\u0438\u0434\u0448\u0430\u0432\u04e3; \u0430\u043a\u0441\u0438 \u043f\u0440\u043e\u0444\u0438\u043b; \u0448\u0430\u04b3\u0440; \u0440\u0430\u049b\u0430\u043c\u0438 \u0442\u0435\u043b\u0435\u0444\u043e\u043d, \u0430\u0433\u0430\u0440 \u0448\u0443\u043c\u043e \u043e\u043d\u0440\u043e \u043d\u0438\u0448\u043e\u043d \u0434\u043e\u0434\u0430 \u0431\u043e\u0448\u0435\u0434; \u044d\u044a\u043b\u043e\u043d\u04b3\u043e, \u0430\u043a\u0441\u04b3\u043e \u0432\u0430 \u0442\u0430\u0432\u0441\u0438\u0444\u0438 \u043e\u043d\u04b3\u043e; \u043c\u0443\u043a\u043e\u0442\u0438\u0431\u0430\u04b3\u043e \u0434\u0430\u0440 \u043f\u0430\u0451\u043c\u04b3\u043e \u0432\u0430 \u043c\u0443\u0440\u043e\u04b7\u0438\u0430\u0442\u04b3\u043e \u0431\u0430 \u0434\u0430\u0441\u0442\u0433\u0438\u0440\u04e3; \u0440\u04ef\u0439\u0445\u0430\u0442\u0438 \u0438\u043d\u0442\u0438\u0445\u043e\u0431\u0448\u0443\u0434\u0430 \u0432\u0430 \u044d\u044a\u043b\u043e\u043d\u04b3\u043e\u0438 \u0434\u0438\u0434\u0430\u0448\u0443\u0434\u0430; \u0448\u0443\u043c\u043e\u0440\u0430\u0438 \u0434\u0438\u0434\u0430\u043d\u0438 \u044d\u044a\u043b\u043e\u043d\u04b3\u043e\u0438 \u0448\u0443\u043c\u043e; \u043c\u0430\u044a\u043b\u0443\u043c\u043e\u0442\u0438 \u0442\u0435\u0445\u043d\u0438\u043a\u0438\u0438 \u0441\u0435\u0440\u0432\u0435\u0440 (IP, \u0432\u0430\u049b\u0442\u0438 \u0434\u0430\u0440\u0445\u043e\u0441\u0442, \u043d\u0430\u0432\u044a\u0438 \u0434\u0430\u0441\u0442\u0433\u043e\u04b3) \u0431\u0430\u0440\u043e\u0438 \u0431\u0435\u0445\u0430\u0442\u0430\u0440\u04e3.")
B.aBz=new A.a4("3. \u0411\u0430\u0440\u043e\u0438 \u0447\u04e3 \u0438\u043d \u043c\u0430\u044a\u043b\u0443\u043c\u043e\u0442 \u043b\u043e\u0437\u0438\u043c \u0430\u0441\u0442","\u0411\u0430\u0440\u043e\u0438 \u043e\u043d \u043a\u0438 \u0432\u043e\u0440\u0438\u0434 \u0448\u0443\u0434\u0430\u043d \u0431\u0430 \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u043a\u043e\u0440 \u043a\u0443\u043d\u0430\u0434, \u0448\u0443\u043c\u043e \u044d\u044a\u043b\u043e\u043d \u0433\u0443\u0437\u043e\u0448\u0442\u0430, \u0431\u043e \u0445\u0430\u0440\u0438\u0434\u043e\u0440\u043e\u043d \u0432\u0430 \u0444\u0443\u0440\u04ef\u0448\u0430\u043d\u0434\u0430\u0433\u043e\u043d \u043d\u0430\u0432\u0438\u0448\u0442\u0430 \u0442\u0430\u0432\u043e\u043d\u0435\u0434, \u0431\u0430 \u043c\u0443\u0440\u043e\u04b7\u0438\u0430\u0442\u04b3\u043e \u0431\u0430 \u0434\u0430\u0441\u0442\u0433\u0438\u0440\u04e3 \u04b7\u0430\u0432\u043e\u0431 \u0434\u0438\u04b3\u0435\u043c, \u044d\u044a\u043b\u043e\u043d\u04b3\u043e\u0440\u043e \u043f\u0435\u0448 \u0430\u0437 \u043d\u0430\u0448\u0440 \u0441\u0430\u043d\u04b7\u0435\u043c \u0432\u0430 \u0445\u0438\u0434\u043c\u0430\u0442\u0440\u043e \u0430\u0437 \u0444\u0438\u0440\u0435\u0431 \u0432\u0430 \u0441\u04ef\u0438\u0438\u0441\u0442\u0438\u0444\u043e\u0434\u0430 \u043c\u0443\u04b3\u043e\u0444\u0438\u0437\u0430\u0442 \u043a\u0443\u043d\u0435\u043c.")
B.aAG=new A.a4("4. \u041c\u0430\u044a\u043b\u0443\u043c\u043e\u0442\u0440\u043e \u0431\u0430 \u043a\u04e3 \u043c\u0435\u0434\u0438\u04b3\u0435\u043c","\u041c\u0430\u044a\u043b\u0443\u043c\u043e\u0442 \u0434\u0430\u0440 \u0441\u0435\u0440\u0432\u0435\u0440\u04b3\u043e\u0438 \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430\u0438 Supabase \u043d\u0438\u0433\u043e\u04b3 \u0434\u043e\u0448\u0442\u0430 \u043c\u0435\u0448\u0430\u0432\u0430\u0434 \u0432\u0430 \u0442\u0430\u0432\u0430\u0441\u0441\u0443\u0442\u0438 \u0445\u043e\u0441\u0442\u0438\u043d\u0433\u0438 Cloudflare Pages \u043f\u0435\u0448\u043d\u0438\u04b3\u043e\u0434 \u043c\u0435\u0433\u0430\u0440\u0434\u0430\u0434. \u041f\u043e\u0447\u0442\u0430\u0438 \u0440\u0430\u043c\u0437\u04b3\u043e\u0438 \u0432\u043e\u0440\u0438\u0434\u0448\u0430\u0432\u04e3 \u0442\u0430\u0432\u0430\u0441\u0441\u0443\u0442\u0438 Brevo \u0444\u0438\u0440\u0438\u0441\u0442\u043e\u0434\u0430 \u043c\u0435\u0448\u0430\u0432\u0430\u0434. \u0417\u0430\u043d\u0433\u0438 \u043e\u0432\u043e\u0437\u04e3 \u0442\u0430\u0432\u0430\u0441\u0441\u0443\u0442\u0438 Agora \u0433\u0443\u0437\u0430\u0440\u043e\u043d\u0438\u0434\u0430 \u043c\u0435\u0448\u0430\u0432\u0430\u0434 (\u043e\u0432\u043e\u0437 \u0441\u0430\u0431\u0442 \u043d\u0430\u043c\u0435\u0448\u0430\u0432\u0430\u0434). \u0425\u0430\u0440\u0438\u0442\u0430\u0438 \u0438\u043d\u0442\u0438\u0445\u043e\u0431\u0438 \u04b7\u043e\u0438 \u044d\u044a\u043b\u043e\u043d \u2014 \u042f\u043d\u0434\u0435\u043a\u0441. \u0412\u043e\u0440\u0438\u0434\u0448\u0430\u0432\u04e3 \u0442\u0430\u0432\u0430\u0441\u0441\u0443\u0442\u0438 Google, Apple \u0432\u0430 Telegram \u0431\u0430 \u043c\u043e \u0442\u0430\u043d\u04b3\u043e \u043d\u043e\u043c, e-mail \u0432\u0430 \u0448\u0438\u043d\u043e\u0441\u0430\u0440\u043e \u043c\u0435\u0434\u0438\u04b3\u0430\u0434. \u041c\u043e \u043c\u0430\u044a\u043b\u0443\u043c\u043e\u0442\u0438 \u0448\u0443\u043c\u043e\u0440\u043e \u043d\u0430\u043c\u0435\u0444\u0443\u0440\u04ef\u0448\u0435\u043c \u0432\u0430 \u0431\u0430\u0440\u043e\u0438 \u0440\u0435\u043a\u043b\u0430\u043c\u0430 \u0431\u0430 \u0448\u0430\u0445\u0441\u0438 \u0441\u0435\u044e\u043c \u043d\u0430\u043c\u0435\u0434\u0438\u04b3\u0435\u043c.")
B.aBg=new A.a4("5. \u041c\u0430\u044a\u043b\u0443\u043c\u043e\u0442\u0438 \u043e\u0448\u043a\u043e\u0440","\u042d\u044a\u043b\u043e\u043d\u0438 \u0448\u0443\u043c\u043e, \u043d\u043e\u043c\u0438 \u0444\u0443\u0440\u04ef\u0448\u0430\u043d\u0434\u0430, \u0448\u0430\u04b3\u0440 \u0432\u0430 \u0442\u0430\u043c\u043e\u0441\u04b3\u043e\u0435, \u043a\u0438 \u0434\u0430\u0440 \u044d\u044a\u043b\u043e\u043d \u043d\u0438\u0448\u043e\u043d \u0434\u043e\u0434\u0430\u0435\u0434, \u0431\u0430\u0440\u043e\u0438 \u04b3\u0430\u043c\u0430\u0438 \u043a\u043e\u0440\u0431\u0430\u0440\u043e\u043d \u043d\u0430\u043c\u043e\u0451\u043d \u0430\u0441\u0442. \u0414\u0430\u0440 \u044d\u044a\u043b\u043e\u043d\u04b3\u043e \u043c\u0430\u044a\u043b\u0443\u043c\u043e\u0442\u0438 \u0448\u0430\u0445\u0441\u0438\u0438 \u0438\u043b\u043e\u0432\u0430\u0433\u0438\u0440\u043e \u043d\u0430\u0433\u0443\u0437\u043e\u0440\u0435\u0434.")
B.aAN=new A.a4("6. \u0422\u043e \u043a\u0430\u0439 \u043d\u0438\u0433\u043e\u04b3 \u043c\u0435\u0434\u043e\u0440\u0435\u043c","\u041c\u0430\u044a\u043b\u0443\u043c\u043e\u0442\u0438 \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u0442\u043e \u0432\u0443\u04b7\u0443\u0434 \u0434\u043e\u0448\u0442\u0430\u043d\u0438 \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u043d\u0438\u0433\u043e\u04b3 \u0434\u043e\u0448\u0442\u0430 \u043c\u0435\u0448\u0430\u0432\u0430\u0434. \u042d\u044a\u043b\u043e\u043d\u04b3\u043e\u0438 \u0431\u043e \u043c\u04ef\u04b3\u043b\u0430\u0442\u0430\u0448\u043e\u043d \u0433\u0443\u0437\u0430\u0448\u0442\u0430 \u043f\u0438\u043d\u04b3\u043e\u043d \u043c\u0435\u0448\u0430\u0432\u0430\u043d\u0434. \u042d\u044a\u043b\u043e\u043d\u04b3\u043e\u0438 \u043d\u0435\u0441\u0442 \u043a\u0430\u0440\u0434\u0430\u0448\u0443\u0434\u0430 \u0430\u0437 \u04b3\u0430\u043c\u0430 \u043f\u0438\u043d\u04b3\u043e\u043d \u0432\u0430 \u0434\u0430\u0440 \u04b7\u0443\u0441\u0442\u0443\u04b7\u04ef \u043d\u0438\u0448\u043e\u043d \u0434\u043e\u0434\u0430 \u043d\u0430\u043c\u0435\u0448\u0430\u0432\u0430\u043d\u0434. \u041f\u0430\u0441 \u0430\u0437 \u0434\u0430\u0440\u0445\u043e\u0441\u0442\u0438 \u043d\u0435\u0441\u0442 \u043a\u0430\u0440\u0434\u0430\u043d\u0438 \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u043e\u043d 14 \u0440\u04ef\u0437 \u043f\u0438\u043d\u04b3\u043e\u043d \u043c\u0435\u0448\u0430\u0432\u0430\u0434: \u0434\u0430\u0440 \u0438\u043d \u043c\u0443\u0434\u0434\u0430\u0442 \u0448\u0443\u043c\u043e \u043c\u0435\u0442\u0430\u0432\u043e\u043d\u0435\u0434 \u0431\u043e \u0432\u043e\u0440\u0438\u0434 \u0448\u0443\u0434\u0430\u043d \u0434\u0443\u0431\u043e\u0440\u0430 \u0431\u0430\u0440\u049b\u0430\u0440\u043e\u0440 \u043a\u0443\u043d\u0435\u0434. \u041f\u0430\u0441 \u0430\u0437 14 \u0440\u04ef\u0437 \u043c\u0430\u044a\u043b\u0443\u043c\u043e\u0442 \u043a\u043e\u043c\u0438\u043b\u0430\u043d \u043d\u0435\u0441\u0442 \u043a\u0430\u0440\u0434\u0430 \u043c\u0435\u0448\u0430\u0432\u0430\u0434.")
B.aAD=new A.a4("7. \u04b2\u0443\u049b\u0443\u049b\u04b3\u043e\u0438 \u0448\u0443\u043c\u043e","\u0428\u0443\u043c\u043e \u043c\u0435\u0442\u0430\u0432\u043e\u043d\u0435\u0434 \u043c\u0430\u044a\u043b\u0443\u043c\u043e\u0442\u0438 \u0445\u0443\u0434\u0440\u043e \u0434\u0430\u0440 \u043f\u0440\u043e\u0444\u0438\u043b \u0442\u0430\u0493\u0439\u0438\u0440 \u0434\u0438\u04b3\u0435\u0434 \u0432\u0430 \u044d\u044a\u043b\u043e\u043d\u04b3\u043e\u0438 \u0445\u0443\u0434\u0440\u043e \u043d\u0435\u0441\u0442 \u043a\u0443\u043d\u0435\u0434. \u04b2\u0438\u0441\u043e\u0431\u0440\u043e \u0434\u0430\u0440 \u0431\u0430\u0440\u043d\u043e\u043c\u0430 \u043d\u0435\u0441\u0442 \u043a\u0430\u0440\u0434\u0430\u043d \u043c\u0443\u043c\u043a\u0438\u043d \u0430\u0441\u0442: \u041f\u0440\u043e\u0444\u0438\u043b \u2192 \xab\u04b2\u0438\u0441\u043e\u0431\u0440\u043e \u043d\u0435\u0441\u0442 \u043a\u0430\u0440\u0434\u0430\u043d\xbb, \u0441\u0438\u043f\u0430\u0441 \u043a\u0430\u043b\u0438\u043c\u0430\u0438 Delete-\u0440\u043e \u043d\u0430\u0432\u0438\u0441\u0435\u0434. \u0414\u0430\u0440\u0445\u043e\u0441\u0442\u0440\u043e \u0438\u043d\u0447\u0443\u043d\u0438\u043d \u0431\u0430 \u0441\u0443\u0440\u043e\u0493\u0430\u0438 e-mail-\u0438 \u0431\u0430\u0445\u0448\u0438 1 \u0444\u0438\u0440\u0438\u0441\u0442\u0435\u0434. \u0428\u0443\u043c\u043e \u04b3\u0430\u049b \u0434\u043e\u0440\u0435\u0434 \u0440\u043e\u0437\u0438\u0433\u0438\u0438 \u0445\u0443\u0434\u0440\u043e \u0431\u0430\u0440\u043e\u0438 \u043a\u043e\u0440\u043a\u0430\u0440\u0434\u0438 \u043c\u0430\u044a\u043b\u0443\u043c\u043e\u0442 \u043f\u0430\u0441 \u0433\u0438\u0440\u0435\u0434, \u0430\u0437 \u0438\u0441\u0442\u0438\u0444\u043e\u0434\u0430\u0438 \u0445\u0438\u0434\u043c\u0430\u0442 \u0434\u0430\u0441\u0442 \u043a\u0430\u0448\u0435\u0434.")
